import React, { useEffect, useState } from 'react';
import { supabase } from '../supabase';

function Dashboard() {
  const [loading, setLoading] = useState(true);
  const [darkMode, setDarkMode] = useState(false);

  useEffect(() => {
    const checkUser = async () => {
      try {
        const { data: { session } } = await supabase.auth.getSession();
        if (!session) {
          window.location.replace('/login');
          return;
        }
      } catch (error) {
        console.error('Session error:', error);
        window.location.replace('/login');
      } finally {
        setLoading(false);
      }
    };

    checkUser();
  }, []);

  const handleSignOut = async () => {
    try {
      await supabase.auth.signOut();
      window.location.replace('/login');
    } catch (error) {
      console.error('Error:', error);
      window.location.replace('/login');
    }
  };

  const toggleDarkMode = () => {
    setDarkMode(!darkMode);
  };

  if (loading) {
    return (
      <div className={`min-h-screen flex items-center justify-center ${darkMode ? 'bg-gray-900' : 'bg-gray-100'}`}>
        <div className={`text-xl ${darkMode ? 'text-gray-200' : 'text-gray-600'}`}>Loading...</div>
      </div>
    );
  }

  return (
    <div className={`min-h-screen p-8 ${darkMode ? 'bg-gray-900' : 'bg-gray-100'}`}>
      <div className={`max-w-4xl mx-auto ${darkMode ? 'bg-gray-800' : 'bg-white'} rounded-lg shadow-lg p-8`}>
        <div className="flex justify-between items-center mb-8">
          <h1 className={`text-2xl font-bold ${darkMode ? 'text-white' : 'text-black'}`}>
            Welcome to Dashboard
          </h1>
          <div className="flex gap-4">
            <button
              onClick={toggleDarkMode}
              className={`px-4 py-2 rounded-md ${
                darkMode 
                  ? 'bg-yellow-500 hover:bg-yellow-600 text-gray-900' 
                  : 'bg-gray-800 hover:bg-gray-900 text-white'
              }`}
            >
              {darkMode ? '☀️ Light' : 'Dark'}
            </button>
            <button
              onClick={handleSignOut}
              className="bg-red-600 text-white px-4 py-2 rounded-md hover:bg-red-700 cursor-pointer"
            >
              Sign Out
            </button>
          </div>
        </div>
        <div className={`${darkMode ? 'bg-gray-700 border-gray-600' : 'bg-blue-50 border-blue-200'} border rounded-lg p-6`}>
          <h2 className={`text-xl font-semibold mb-4 ${darkMode ? 'text-white' : 'text-black'}`}>Getting Started</h2>
          <p className={darkMode ? 'text-gray-300' : 'text-gray-700'}>
            Welcome to your dashboard! You've successfully logged in to your account.
          </p>
        </div>
      </div>
    </div>
  );
}

export default Dashboard;
